// GENERATED by port-tests.py from ../xb-chat/test: the Node tests, run against the Rust server.
// End-to-end encryption: the Signal protocol core on both crypto backends,
// and the whole system with Node and browser clients, checking that the
// server only ever handles ciphertext.

import assert from 'node:assert/strict';
import { randomBytes } from 'node:crypto';
import { promises as fs } from 'node:fs';
import net from 'node:net';
import os from 'node:os';
import path from 'node:path';
import { after, before, describe, test } from 'node:test';
import { startRust } from './rust.js';
import { Client } from '../../xb-chat/clients/node/client.js';
import { MemoryKeyStore, nodeCrypto } from '../../xb-chat/clients/node/signal-node.js';
import { encode } from '../../xb-chat/protocol/codec.js';
import { generateKeyPair } from '../../xb-chat/protocol/noise.js';
import { SenderKeys, SignalProtocol } from '../../xb-chat/protocol/signal.js';
import { Transport } from '../../xb-chat/protocol/transport.js';
import { WebClient } from '../../xb-chat/clients/web/js/client.js';
import { generateKeyPair as webKeyPair } from '../../xb-chat/clients/web/js/noise.js';
import { webCrypto } from '../../xb-chat/clients/web/js/signal-web.js';

const te = new TextEncoder();
const td = new TextDecoder();

// ---------------------------------------------------------------- protocol core

async function device(crypto = nodeCrypto) {
  const p = new SignalProtocol({ crypto, store: new MemoryKeyStore() });
  await p.identity();
  return p;
}

// What the server would hand out for `p`, using one one-time pre-key.
async function bundleOf(p, { prekey = true } = {}) {
  const id = await p.identity();
  const spk = await p.signedPreKey();
  const [opk] = prekey ? await p.newPreKeys(1) : [null];
  return { identity: id.dh.public, signing: id.sign.public, spk: { id: spk.id, public: spk.keyPair.public, sig: spk.sig }, prekey: opk };
}

async function pair(aCrypto = nodeCrypto, bCrypto = nodeCrypto) {
  const alice = await device(aCrypto);
  const bob = await device(bCrypto);
  const A = `alice.${(await alice.identity()).device}`;
  const B = `bob.${(await bob.identity()).device}`;
  await alice.initOutgoing(B, await bundleOf(bob));
  const send = async (from, addr, text) => from.encrypt(addr, te.encode(text));
  const recv = async (to, user, m) => td.decode((await to.decrypt(user, m.type, m.body)).plaintext);
  return { alice, bob, A, B, send, recv };
}

describe('signal protocol', () => {
  test('X3DH + ratchet, both directions, several DH ratchet steps', async () => {
    const { alice, bob, A, B, send, recv } = await pair();
    const first = await send(alice, B, 'hi bob');
    assert.equal(first.type, 'pkmsg');
    assert.equal(await recv(bob, 'alice', first), 'hi bob');
    for (let round = 0; round < 3; round++) {
      const r = await send(bob, A, `reply ${round}`);
      assert.equal(r.type, 'msg');
      assert.equal(await recv(alice, 'bob', r), `reply ${round}`);
      const m = await send(alice, B, `again ${round}`);
      assert.equal(m.type, 'msg', 'Alice stops sending pkmsg once Bob answered');
      assert.equal(await recv(bob, 'alice', m), `again ${round}`);
    }
  });

  test('out-of-order and lost messages, across ratchet steps', async () => {
    const { alice, bob, A, B, send, recv } = await pair();
    const batch1 = [];
    for (let i = 0; i < 5; i++) batch1.push(await send(alice, B, `a${i}`));
    // Bob sees the 4th first: it is a pkmsg too, so the session starts from it.
    assert.equal(await recv(bob, 'alice', batch1[3]), 'a3');
    assert.equal(await recv(bob, 'alice', batch1[0]), 'a0');
    assert.equal(await recv(bob, 'alice', batch1[4]), 'a4');

    const reply = await send(bob, A, 'b0');
    assert.equal(await recv(alice, 'bob', reply), 'b0');
    const batch2 = [await send(alice, B, 'c0'), await send(alice, B, 'c1')];
    // New chain first, then the stragglers of the old one.
    assert.equal(await recv(bob, 'alice', batch2[1]), 'c1');
    assert.equal(await recv(bob, 'alice', batch1[2]), 'a2');
    assert.equal(await recv(bob, 'alice', batch2[0]), 'c0');
    assert.equal(await recv(bob, 'alice', batch1[1]), 'a1');
  });

  test('a redelivered copy decrypts until released, then is a duplicate', async () => {
    const { alice, bob, B, send } = await pair();
    const m = await send(alice, B, 'once');
    const r1 = await bob.decrypt('alice', m.type, m.body);
    const r2 = await bob.decrypt('alice', m.type, m.body); // crash before the receipt
    assert.equal(td.decode(r2.plaintext), 'once');
    await bob.release(r1.ref);
    await assert.rejects(bob.decrypt('alice', m.type, m.body), { code: 'duplicate' });
  });

  test('both sides start a session at once and still converge', async () => {
    const alice = await device();
    const bob = await device();
    const A = `alice.${(await alice.identity()).device}`;
    const B = `bob.${(await bob.identity()).device}`;
    await alice.initOutgoing(B, await bundleOf(bob));
    await bob.initOutgoing(A, await bundleOf(alice));
    const fromA = await alice.encrypt(B, te.encode('from alice'));
    const fromB = await bob.encrypt(A, te.encode('from bob'));
    assert.equal(td.decode((await bob.decrypt('alice', fromA.type, fromA.body)).plaintext), 'from alice');
    assert.equal(td.decode((await alice.decrypt('bob', fromB.type, fromB.body)).plaintext), 'from bob');
    for (let i = 0; i < 3; i++) {
      const x = await alice.encrypt(B, te.encode(`x${i}`));
      assert.equal(td.decode((await bob.decrypt('alice', x.type, x.body)).plaintext), `x${i}`);
      const y = await bob.encrypt(A, te.encode(`y${i}`));
      assert.equal(td.decode((await alice.decrypt('bob', y.type, y.body)).plaintext), `y${i}`);
    }
  });

  test('tampering and forged pre-keys are caught', async () => {
    const { bob, B, alice, send } = await pair();
    const m = await send(alice, B, 'secret');
    const bad = new Uint8Array(m.body);
    bad[bad.length - 20] ^= 1;
    await assert.rejects(bob.decrypt('alice', m.type, bad));
    const header = new Uint8Array(m.body);
    header[1] ^= 1; // sender device is authenticated too
    await assert.rejects(bob.decrypt('alice', m.type, header));

    const mallory = await device();
    const forged = await bundleOf(bob);
    forged.spk.public = (await mallory.signedPreKey()).keyPair.public; // server swaps the signed pre-key
    await assert.rejects(alice.initOutgoing('bob.99', forged), { code: 'bad-signature' });
  });

  test('works without one-time pre-keys (server ran out)', async () => {
    const alice = await device();
    const bob = await device();
    const B = `bob.${(await bob.identity()).device}`;
    await alice.initOutgoing(B, await bundleOf(bob, { prekey: false }));
    const m = await alice.encrypt(B, te.encode('no opk'));
    assert.equal(td.decode((await bob.decrypt('alice', m.type, m.body)).plaintext), 'no opk');
  });

  test('sender keys: one ciphertext for the group, redelivery, forgery', async () => {
    const group = '1700000000001@g.xb';
    const ana = new SenderKeys({ crypto: nodeCrypto, store: new MemoryKeyStore() });
    const ben = new SenderKeys({ crypto: webCrypto, store: new MemoryKeyStore() });
    const own = await ana.own(group);
    // What ana's distribution carries: where her chain is now.
    await ben.install(group, 'ana.7', { id: own.id, iteration: own.iteration, chain: own.chain, signing: own.sign.public });
    const m = [];
    for (let i = 0; i < 4; i++) m.push(await ana.encrypt(group, 7, te.encode(`g${i}`)));
    // Out of order, and the same one twice until it's released.
    const r2 = await ben.decrypt(group, 'ana', m[2]);
    assert.equal(td.decode(r2.plaintext), 'g2');
    assert.equal(td.decode((await ben.decrypt(group, 'ana', m[0])).plaintext), 'g0');
    assert.equal(td.decode((await ben.decrypt(group, 'ana', m[2])).plaintext), 'g2');
    await ben.release(r2.ref);
    await assert.rejects(ben.decrypt(group, 'ana', m[2]), { code: 'duplicate' });
    // Another member can't pass a message off as ana's: no signature.
    const forged = new Uint8Array(m[3]);
    forged[20] ^= 1;
    await assert.rejects(ben.decrypt(group, 'ana', forged), { code: 'bad-signature' });
    // Another group, or no key: refused.
    await assert.rejects(ben.decrypt('1700000000002@g.xb', 'ana', m[3]), { code: 'no-sender-key' });
    assert.equal(td.decode((await ben.decrypt(group, 'ana', m[3])).plaintext), 'g3');
  });

  test('node:crypto and WebCrypto backends interoperate', async () => {
    for (const [a, b] of [
      [nodeCrypto, webCrypto],
      [webCrypto, nodeCrypto],
    ]) {
      const { alice, bob, A, B, send, recv } = await pair(a, b);
      assert.equal(await recv(bob, 'alice', await send(alice, B, 'one')), 'one');
      assert.equal(await recv(alice, 'bob', await send(bob, A, 'two')), 'two');
      const late = await send(alice, B, 'late');
      assert.equal(await recv(bob, 'alice', await send(alice, B, 'early')), 'early');
      assert.equal(await recv(bob, 'alice', late), 'late');
    }
  });
});

// ---------------------------------------------------------------- whole system

let dir, chat, media, web, base, wsUrl;
const open = [];
const seenByServer = []; // every stanza the server received, encoded
const nodeKeys = new Map();
const webKeys = new Map();
const keysOf = (map, user) => {
  if (!map.has(user)) map.set(user, new MemoryKeyStore());
  return map.get(user);
};

before(async () => {
  dir = await fs.mkdtemp(path.join(os.tmpdir(), 'xb-e2ee-'));
  chat = await startRust({ dir });
  media = chat.media;
  base = chat.base;
  wsUrl = chat.wsUrl;
});

after(async () => {
  for (const c of open) c.close();
  await chat.close();
  await fs.rm(dir, { recursive: true, force: true });
});

const next = (em, ev, filter = () => true, ms = 4000) =>
  new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`timed out waiting for ${ev}`)), ms);
    const on = (v) => {
      if (!filter(v)) return;
      clearTimeout(timer);
      em.off(ev, on);
      resolve(v);
    };
    em.on(ev, on);
  });
const tick = (ms = 50) => new Promise((r) => setTimeout(r, ms));

async function tcp(user, { register = false, keyStore = keysOf(nodeKeys, user), ...opts } = {}) {
  const c = new Client({ port: chat.port, serverPublicKey: chat.publicKey, keyStore, ...opts });
  c.on('error', () => {});
  open.push(c);
  await c.connect();
  await (register ? c.register(user, 'password1') : c.login(user, 'password1'));
  return c;
}

const webDeviceKeys = new Map();
async function browser(user, { register = false } = {}) {
  if (!webDeviceKeys.has(user)) webDeviceKeys.set(user, await webKeyPair());
  const c = new WebClient({
    url: wsUrl,
    staticKeyPair: webDeviceKeys.get(user),
    mediaBase: base,
    serverPublicKey: chat.publicKey,
    keyStore: keysOf(webKeys, user),
  });
  c.on('error', () => {});
  open.push(c);
  await c.connect();
  await (register ? c.register(user, 'password1') : c.login(user, 'password1'));
  return c;
}

// True if `needle` occurs in anything the server received or stored.
async function serverSaw(needle) {
  return chat.store.saw(Buffer.from(needle).toString('base64'));
}

describe('end-to-end encrypted chat', () => {
  before(async () => {
    for (const u of ['ana', 'ben']) (await tcp(u, { register: true })).close();
    for (const u of ['wendy']) (await browser(u, { register: true })).close();
    await tick();
  });

  test('the server refuses plaintext bodies', async () => {
    const sock = net.connect(chat.port, '127.0.0.1');
    const t = new Transport(sock, { initiator: true, staticKeyPair: generateKeyPair() });
    t.on('error', () => {});
    const nodes = [];
    t.on('node', (n) => nodes.push(n));
    await new Promise((r) => {
      t.once('ready', r);
      sock.once('connect', () => t.start());
    });
    t.send({ tag: 'auth', attrs: { user: 'ana', pass: 'password1' } });
    const until = async (fn) => {
      for (let i = 0; i < 100 && !fn(); i++) await tick(30);
    };
    await until(() => nodes.some((n) => n.tag === 'success'));
    for (const [id, content] of [
      ['P1', [{ tag: 'body', attrs: {}, content: Buffer.from('plain') }]],
      ['P2', [{ tag: 'media', attrs: { url: 'x', key: 'k' } }]],
      ['P3', 'text'],
    ]) {
      t.send({ tag: 'message', attrs: { id, to: 'ben@s.xb' }, content });
    }
    await until(() => nodes.filter((n) => n.tag === 'ack').length >= 3);
    const acks = nodes.filter((n) => n.tag === 'ack').map((n) => [n.attrs.id, n.attrs.error]);
    assert.deepEqual(acks, [
      ['P1', 'bad-request'],
      ['P2', 'bad-request'],
      ['P3', 'bad-request'],
    ]);
    assert.equal(await chat.store.pendingCount('ben'), 0);
    t.end();
  });

  test('Node <-> browser, text and media: the server sees only ciphertext', async () => {
    const ana = await tcp('ana');
    const wendy = await browser('wendy');
    const secret1 = `node-to-web ${randomBytes(8).toString('hex')}`;
    const secret2 = `web-to-node ${randomBytes(8).toString('hex')}`;

    const atWeb = next(wendy, 'message');
    await ana.sendMessage('wendy', secret1);
    const m1 = await atWeb;
    assert.equal(m1.text, secret1);
    assert.equal(m1.from, 'ana@s.xb');

    const atNode = next(ana, 'message');
    const delivered = next(wendy, 'receipt', (r) => r.type === 'delivered');
    const ack = await wendy.sendMessage('ana@s.xb', secret2);
    assert.equal((await atNode).text, secret2);
    assert.equal((await delivered).id, ack.id);

    // Media: the key travels inside the encrypted message now.
    const photo = new Uint8Array(randomBytes(20_000));
    const atNode2 = next(ana, 'message');
    await wendy.sendMedia('ana@s.xb', photo, { mimetype: 'image/png', caption: 'secret caption' });
    const m3 = await atNode2;
    assert.ok((await ana.downloadMedia(m3.media)).equals(Buffer.from(photo)));

    await tick();
    for (const s of [secret1, secret2, 'secret caption', m3.media.key, Buffer.from(m3.media.key, 'base64')]) {
      assert.equal(await serverSaw(s), false, `server saw ${s}`);
    }
    ana.close();
    wendy.close();
  });

  test('offline delivery to the browser, many messages, all decrypt in order', async () => {
    const ben = await tcp('ben');
    const texts = Array.from({ length: 20 }, (_, i) => `queued ${i}`);
    for (const t of texts) await ben.sendMessage('wendy', t);
    ben.close();
    await tick();
    assert.equal(await chat.store.pendingCount('wendy'), 20);

    const wendy = new WebClient({
      url: wsUrl,
      staticKeyPair: webDeviceKeys.get('wendy'),
      mediaBase: base,
      serverPublicKey: chat.publicKey,
      keyStore: keysOf(webKeys, 'wendy'),
    });
    wendy.on('error', () => {});
    open.push(wendy);
    const got = [];
    // Like the app: an async save before the delivered receipt.
    wendy.messageHandler = async (m) => {
      await tick(1);
      got.push(m.text);
    };
    await wendy.connect();
    await wendy.login('wendy', 'password1');
    for (let i = 0; i < 50 && got.length < 20; i++) await tick();
    assert.deepEqual(got, texts);
    await tick();
    assert.equal(await chat.store.pendingCount('wendy'), 0);
    wendy.close();
  });

  test('a browser that crashes before its receipt decrypts the redelivered copy', async () => {
    const ana = await tcp('ana');
    let wendy = await browser('wendy');
    const first = next(wendy, 'message');
    wendy.messageHandler = () => new Promise(() => {}); // never finishes saving: no receipt
    await ana.sendMessage('wendy', 'did you get this?');
    await first;
    wendy.close();
    await tick();
    assert.equal(await chat.store.pendingCount('wendy'), 1);

    const again = new WebClient({
      url: wsUrl,
      staticKeyPair: webDeviceKeys.get('wendy'),
      mediaBase: base,
      serverPublicKey: chat.publicKey,
      keyStore: keysOf(webKeys, 'wendy'),
    });
    again.on('error', () => {});
    open.push(again);
    const redelivered = next(again, 'message');
    await again.connect();
    await again.login('wendy', 'password1');
    assert.equal((await redelivered).text, 'did you get this?');
    await tick();
    assert.equal(await chat.store.pendingCount('wendy'), 0);
    ana.close();
    again.close();
  });

  test('group of Node and browser members: pairwise fan-out, each gets only its own ciphertext', async () => {
    const ana = await tcp('ana');
    const ben = await tcp('ben');
    const wendy = await browser('wendy');
    const g = await ana.createGroup('Mixed', ['ben', 'wendy']);
    const secret = `group ${randomBytes(8).toString('hex')}`;

    const atBen = next(ben, 'message');
    const atWendy = next(wendy, 'message');
    const sent = await ana.sendGroupMessage(g.id, secret);
    for (const m of [await atBen, await atWendy]) {
      assert.equal(m.text, secret);
      assert.equal(m.from, g.jid);
      assert.equal(m.participant, 'ana@s.xb');
      assert.equal(m.id, sent.id);
    }

    const fromWeb = `from the browser ${randomBytes(4).toString('hex')}`;
    const atAna = next(ana, 'message');
    const atBen2 = next(ben, 'message');
    await wendy.sendMessage(g.jid, fromWeb);
    assert.equal((await atAna).text, fromWeb);
    assert.equal((await atBen2).text, fromWeb);
    assert.equal(await serverSaw(secret), false);
    assert.equal(await serverSaw(fromWeb), false);
    for (const c of [ana, ben, wendy]) c.close();
  });

  test('group sender keys: the key goes to each device once, then one ciphertext for all', async () => {
    const ana = await tcp('ana');
    const ben = await tcp('ben');
    const wendy = await browser('wendy');
    const g = await ana.createGroup('Keys', ['ben', 'wendy']);
    const sent = [];
    const send = ana.send.bind(ana);
    ana.send = (node) => {
      if (node.tag === 'message') sent.push(node);
      return send(node);
    };
    const pairwise = (node) => node.content[0].content.flatMap((to) => to.content).length;
    for (let i = 0; i < 3; i++) {
      const at = [next(ben, 'message'), next(wendy, 'message')];
      await ana.sendGroupMessage(g.id, `round ${i}`);
      for (const m of await Promise.all(at)) assert.equal(m.text, `round ${i}`);
    }
    assert.equal(pairwise(sent[0]), 2, 'the first message gives the key to both devices');
    assert.equal(pairwise(sent[1]), 0, 'after that: no per-device ciphertext');
    assert.equal(pairwise(sent[2]), 0);
    for (const n of sent) assert.equal(n.content[1].attrs.type, 'skmsg');

    // Ben leaves the group's devices: a new chain, given to wendy again.
    await ana.removeFromGroup(g.id, ['ben']);
    const carl = await tcp('carl', { register: true });
    await ana.addToGroup(g.id, ['carl']);
    const atWendy = next(wendy, 'message');
    const atCarl = next(carl, 'message');
    let atBen = false;
    ben.on('message', () => (atBen = true));
    await ana.sendGroupMessage(g.id, 'after the change');
    assert.equal((await atWendy).text, 'after the change');
    assert.equal((await atCarl).text, 'after the change');
    await tick();
    assert.equal(atBen, false);
    const last = sent.at(-1);
    assert.equal(pairwise(last), 2, 'new chain: wendy and carl get the new key');
    assert.equal(await serverSaw('after the change'), false);
    for (const c of [ana, ben, carl, wendy]) c.close();
  });

  test('a new device of the recipient: the server says stale-devices and the sender re-encrypts', async () => {
    const ana = await tcp('ana');
    const ben = await tcp('ben');
    const first = next(ben, 'message');
    await ana.sendMessage('ben', 'to one device'); // ana now has ben's device list cached
    await first;
    ben.close();

    // Ben adds a browser: a second device with its own keys.
    const benWeb = await browser('ben');
    const atWeb = next(benWeb, 'message');
    await ana.sendMessage('ben', 'to both devices');
    assert.equal((await atWeb).text, 'to both devices');
    assert.equal((await chat.store.keyDevices('ben')).length, 2);
    benWeb.close();

    // Back on the terminal device: it can read what was sent to both.
    await ana.sendMessage('ben', 'read me on the terminal');
    const ben2 = await tcp('ben');
    // (queued while ben was offline)
    const m = await next(ben2, 'message', (x) => x.text === 'read me on the terminal');
    assert.ok(m);
    ana.close();
    ben2.close();
  });

  test('one-time pre-keys are handed out once each and topped up at login', async () => {
    const dev = String((await keysOf(webKeys, 'wendy').get('identity', 'self')).device);
    const { registered, count } = await chat.store.keyCount('wendy', dev);
    assert.ok(registered && count > 0);
    const ana = await tcp('ana');
    const ids = new Set();
    for (let i = 0; i < count + 1; i++) {
      const res = await ana.iq('encrypt', 'get', [{ tag: 'key', attrs: {}, content: [{ tag: 'user', attrs: { jid: 'wendy@s.xb', device: dev } }] }]);
      const key = res.content[0].content[0].content[0].content.find((n) => n.tag === 'key');
      if (key) ids.add(key.attrs.id);
      else assert.equal(i, count, 'only the last fetch finds none left');
    }
    assert.equal(ids.size, count, 'never the same one-time pre-key twice');
    assert.equal((await chat.store.keyCount('wendy', dev)).count, 0);
    const wendy = await browser('wendy');
    assert.ok((await chat.store.keyCount('wendy', dev)).count >= 15, 'topped up after login');
    ana.close();
    wendy.close();
  });

  test('unknown recipients and users without keys', async () => {
    const ana = await tcp('ana');
    await assert.rejects(ana.sendMessage('nobody', 'hi'), { code: 'item-not-found' });
    // An account that never published keys (logged in by a raw transport, say).
    {
      const sock = net.connect(chat.port, '127.0.0.1');
      const t = new Transport(sock, { initiator: true, staticKeyPair: generateKeyPair() });
      t.on('error', () => {});
      await new Promise((r) => {
        t.once('ready', r);
        sock.once('connect', () => t.start());
      });
      const answered = new Promise((r) => t.once('node', r));
      t.send({ tag: 'auth', attrs: { mode: 'register', user: 'nokeys', pass: 'password1' } });
      assert.equal((await answered).tag, 'success');
      sock.destroy();
    }
    await assert.rejects(ana.sendMessage('nokeys', 'hi'), { code: 'no-keys' });
    ana.close();
  });
});
